import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

suspend fun handle(id: String): Result = coroutineScope {   // structured: children bounded
    // concurrent children: coroutineScope cancels them all on the first failure
    val user   = async(Dispatchers.IO) { fetchUser(id) }
    val orders = async(Dispatchers.IO) { fetchOrders(user.await()) }
    Result(user.await(), orders.await())
}

// Flow: a cold stream that suspends per element (a coroutine pipeline)
fun users(): Flow<User> = flow {
    for (id in ids) emit(fetchUser(id))       // emit suspends; backpressure is natural
}.flowOn(Dispatchers.IO)

// launch inside a scope is structured; GlobalScope.launch is a leak.
// NEVER block a dispatcher thread - use Dispatchers.IO for blocking calls.
// A suspend call that does not actually suspend still costs a state-machine hop.
